text:
CSS
/* styles.css */
:root {
  --cream: #fff8ec;
  --cream-2: #fff2dc;
  --paper: #fffdf7;
  --paper-soft: #fff9ef;
  --yellow: #ffd84d;
  --yellow-deep: #efb821;
  --green: #4f7b2c;
  --green-dark: #2f4d1e;
  --olive: #65773a;
  --coral: #f06d38;
  --tomato: #b73520;
  --brown: #3b1b12;
  --brown-2: #693827;
  --muted: #826d5d;
  --line: #eadcc8;
  --line-strong: #dac6aa;
  --shadow: 0 24px 70px rgba(75, 43, 22, 0.12);
  --soft-shadow: 0 12px 30px rgba(87, 54, 28, 0.1);
  --radius-xl: 34px;
  --radius-lg: 22px;
  --radius-md: 16px;
  --radius-sm: 12px;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  color: var(--brown);
  background:
    radial-gradient(circle at 5% 8%, rgba(255, 216, 77, 0.24), transparent 24rem),
    radial-gradient(circle at 95% 10%, rgba(79, 123, 44, 0.12), transparent 22rem),
    linear-gradient(180deg, #fffdf7 0%, var(--cream) 100%);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font: inherit;
}

.bg-doodle {
  position: fixed;
  z-index: 0;
  color: rgba(79, 123, 44, 0.18);
  font-family: Georgia, serif;
  pointer-events: none;
  user-select: none;
}

.bg-doodle-left {
  left: 24px;
  bottom: 34px;
  font-size: 9rem;
  transform: rotate(-18deg);
}

.bg-doodle-right {
  top: 28px;
  right: 42px;
  font-size: 7rem;
  color: rgba(240, 109, 56, 0.16);
  transform: rotate(16deg);
}

.app-shell {
  position: relative;
  z-index: 1;
  width: min(1360px, calc(100% - 36px));
  margin: 0 auto;
  padding: 24px 0 64px;
}

.topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
  padding: 0 8px;
}

.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 1.5rem;
  font-weight: 900;
  letter-spacing: -0.04em;
  color: var(--green-dark);
}

.wordmark-mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 2px solid var(--green-dark);
  border-radius: 50%;
  background: var(--paper);
  box-shadow: 0 6px 0 rgba(47, 77, 30, 0.12);
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--brown-2);
  font-weight: 800;
  font-size: 0.88rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.desktop-nav a {
  padding: 12px 15px;
  border-radius: 999px;
}

.desktop-nav a:hover {
  background: rgba(255, 216, 77, 0.38);
}

.calculator-card {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.8), rgba(255, 249, 239, 0.96)),
    radial-gradient(circle at 3% 5%, rgba(79, 123, 44, 0.08), transparent 17rem);
  border: 1px solid var(--line);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.hero-utility {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 24px;
  align-items: start;
  padding: 34px 36px 24px;
}

.hero-copy {
  text-align: center;
  justify-self: center;
  max-width: 720px;
}

.eyebrow {
  margin: 0 0 8px;
  font-size: 0.78rem;
  font-weight: 900;
  color: var(--green);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 8px;
  font-family: Georgia, "Times New Roman", serif;
  color: var(--brown);
  font-size: clamp(2.05rem, 4vw, 3.35rem);
  line-height: 0.95;
  letter-spacing: -0.065em;
}

.lede {
  margin-bottom: 0;
  color: var(--brown-2);
  font-size: 1rem;
  line-height: 1.55;
}

.top-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 10px;
  min-width: 355px;
}

.action,
.summary-button,
.mobile-total-actions button {
  border: 1px solid var(--line-strong);
  background: var(--paper);
  color: var(--brown);
  border-radius: 999px;
  padding: 10px 14px;
  font-weight: 900;
  font-size: 0.84rem;
  cursor: pointer;
  box-shadow: 0 4px 0 rgba(80, 49, 26, 0.08);
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.action:hover,
.summary-button:hover,
.mobile-total-actions button:hover {
  transform: translateY(-1px);
  box-shadow: 0 7px 0 rgba(80, 49, 26, 0.1);
}

.action:active,
.summary-button:active,
.mobile-total-actions button:active {
  transform: translateY(1px);
  box-shadow: 0 2px 0 rgba(80, 49, 26, 0.1);
}

.action-warn {
  color: var(--coral);
  border-color: rgba(240, 109, 56, 0.35);
}

.action-green {
  color: var(--green);
  border-color: rgba(79, 123, 44, 0.35);
}

.action-outline {
  background: transparent;
  border-color: rgba(183, 53, 32, 0.36);
  color: var(--tomato);
}

.totals-band {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 0;
  margin: 0 36px 26px;
  border: 1px solid rgba(122, 83, 19, 0.2);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(255, 235, 120, 0.95), rgba(255, 211, 61, 0.98)),
    radial-gradient(circle at 10% 0%, rgba(255, 255, 255, 0.65), transparent 22rem);
  box-shadow: 0 16px 34px rgba(190, 130, 18, 0.18);
  overflow: hidden;
}

.stat-tile {
  min-height: 96px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 18px 16px;
  border-right: 1px solid rgba(116, 80, 25, 0.17);
}

.stat-tile:last-child {
  border-right: 0;
}

.stat-icon {
  display: grid;
  place-items: center;
  width: 36px;
  min-width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255, 253, 247, 0.52);
  font-size: 1.25rem;
}

.stat-text {
  min-width: 0;
  display: grid;
  grid-template-columns: auto auto;
  align-items: end;
  gap: 0 4px;
}

.stat-label {
  grid-column: 1 / -1;
  margin-bottom: 3px;
  font-size: 0.72rem;
  font-weight: 950;
  line-height: 1;
  color: var(--brown-2);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.stat-text strong {
  font-size: clamp(1.36rem, 2vw, 2rem);
  line-height: 0.9;
  letter-spacing: -0.04em;
}

.stat-unit {
  margin-bottom: 2px;
  color: var(--brown-2);
  font-size: 0.76rem;
  font-weight: 800;
}

.section-block {
  margin: 0 24px 14px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: rgba(255, 253, 247, 0.72);
}

.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 14px;
}

.section-heading > div {
  display: flex;
  align-items: center;
  gap: 11px;
}

.section-heading h2 {
  margin: 0;
  color: var(--brown);
  font-size: 1.08rem;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.section-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.4;
}

.step-badge,
.lightning,
.scale-icon {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  border-radius: 50%;
  background: var(--yellow);
  color: var(--brown);
  font-weight: 950;
  box-shadow: 0 4px 0 rgba(105, 56, 39, 0.13);
}

.lightning,
.scale-icon {
  background: transparent;
  color: var(--coral);
  font-size: 1.35rem;
  box-shadow: none;
}

.format-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  border: 1px solid var(--line-strong);
  border-radius: 18px;
  overflow: hidden;
  background: var(--paper);
}

.format-card {
  min-width: 0;
  display: grid;
  place-items: center;
  gap: 8px;
  padding: 16px 12px 14px;
  border: 0;
  border-right: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.68), rgba(255, 249, 239, 0.88));
  color: var(--brown);
  cursor: pointer;
  position: relative;
}

.format-card:last-child {
  border-right: 0;
}

.format-card::after {
  content: "";
  position: absolute;
  inset: 8px;
  border-radius: 14px;
  border: 2px solid transparent;
  pointer-events: none;
  transition: border-color 0.18s ease, background 0.18s ease;
}

.format-card:hover::after {
  border-color: rgba(79, 123, 44, 0.25);
}

.format-card.is-active::after {
  border-color: var(--green);
  background: rgba(79, 123, 44, 0.05);
}

.format-card strong {
  position: relative;
  z-index: 1;
  font-size: 0.88rem;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.format-card small {
  position: relative;
  z-index: 1;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 800;
}

.thumb {
  --size: 70px;
  position: relative;
  display: grid;
  place-items: center;
  width: var(--size);
  height: calc(var(--size) * 0.72);
  border: 1px solid rgba(97, 69, 45, 0.15);
  border-radius: 999px;
  overflow: hidden;
  box-shadow:
    inset 0 0 18px rgba(255, 255, 255, 0.42),
    0 8px 18px rgba(65, 38, 22, 0.14);
  isolation: isolate;
}

.thumb::before,
.thumb::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
}

.thumb::after {
  background:
    radial-gradient(circle at 25% 26%, rgba(255, 255, 255, 0.7), transparent 13%),
    radial-gradient(circle at 70% 80%, rgba(50, 30, 17, 0.14), transparent 22%);
  mix-blend-mode: soft-light;
}

.thumb span {
  font-size: calc(var(--size) * 0.36);
  filter: drop-shadow(0 3px 4px rgba(48, 28, 13, 0.2));
}

.thumb-bowl::before {
  background:
    radial-gradient(circle at 34% 50%, #7b3b22 0 9%, transparent 10%),
    radial-gradient(circle at 62% 40%, #6aaa3a 0 12%, transparent 13%),
    radial-gradient(circle at 45% 35%, #f36f2d 0 9%, transparent 10%),
    radial-gradient(circle at 70% 63%, #f2cf6b 0 8%, transparent 9%),
    linear-gradient(135deg, #fff7dc, #d9ad72);
}

.thumb-burrito::before {
  background:
    radial-gradient(circle at 68% 47%, #ef6b30 0 10%, transparent 11%),
    radial-gradient(circle at 72% 58%, #6aa83a 0 8%, transparent 9%),
    linear-gradient(115deg, #e9c482 0 38%, #f8e2af 39% 66%, #b77b45 67% 100%);
}

.thumb-salad::before {
  background:
    radial-gradient(circle at 30% 50%, #8dbd50 0 12%, transparent 13%),
    radial-gradient(circle at 48% 40%, #ed5231 0 7%, transparent 8%),
    radial-gradient(circle at 64% 57%, #f3cf6f 0 10%, transparent 11%),
    linear-gradient(135deg, #dff2b8, #fff8d8);
}

.thumb-tacos::before {
  background:
    radial-gradient(circle at 42% 50%, #d64628 0 8%, transparent 9%),
    radial-gradient(circle at 58% 42%, #69a83d 0 8%, transparent 9%),
    linear-gradient(115deg, #e6b44a 0 30%, #ffe08a 31% 70%, #c88331 71% 100%);
}

.thumb-quesadilla::before {
  background:
    radial-gradient(circle at 60% 45%, rgba(123, 63, 24, 0.38) 0 9%, transparent 10%),
    radial-gradient(circle at 37% 62%, rgba(255, 255, 255, 0.56) 0 12%, transparent 13%),
    linear-gradient(135deg, #e6a94f, #ffe6a0 48%, #c87935);
}

.thumb-rice::before {
  background:
    radial-gradient(circle at 20% 32%, #fff8de 0 7%, transparent 8%),
    radial-gradient(circle at 42% 53%, #f1dc9c 0 7%, transparent 8%),
    radial-gradient(circle at 70% 35%, #fff1c7 0 8%, transparent 9%),
    radial-gradient(circle at 62% 72%, #d4b069 0 7%, transparent 8%),
    linear-gradient(145deg, #fff6d7, #d8bd7c);
}

.thumb-beans::before {
  background:
    radial-gradient(circle at 22% 35%, #2d130d 0 10%, transparent 11%),
    radial-gradient(circle at 47% 44%, #5a2417 0 12%, transparent 13%),
    radial-gradient(circle at 72% 61%, #8d4b26 0 10%, transparent 11%),
    radial-gradient(circle at 36% 72%, #31150f 0 10%, transparent 11%),
    linear-gradient(135deg, #32120d, #a45b2e);
}

.thumb-protein::before {
  background:
    radial-gradient(circle at 28% 50%, #d5792c 0 13%, transparent 14%),
    radial-gradient(circle at 52% 36%, #a64422 0 10%, transparent 11%),
    radial-gradient(circle at 68% 60%, #f0a340 0 12%, transparent 13%),
    linear-gradient(135deg, #f2b45e, #6c2b18);
}

.thumb-salsa::before {
  background:
    radial-gradient(circle at 20% 30%, #d62c20 0 8%, transparent 9%),
    radial-gradient(circle at 43% 58%, #f14625 0 10%, transparent 11%),
    radial-gradient(circle at 70% 38%, #ffcd55 0 8%, transparent 9%),
    radial-gradient(circle at 65% 70%, #5da23e 0 7%, transparent 8%),
    linear-gradient(145deg, #f26431, #b52318);
}

.thumb-toppings::before {
  background:
    radial-gradient(circle at 24% 38%, #fff0a7 0 11%, transparent 12%),
    radial-gradient(circle at 49% 62%, #f7d25a 0 11%, transparent 12%),
    radial-gradient(circle at 70% 36%, #8abf53 0 10%, transparent 11%),
    linear-gradient(135deg, #fff5bf, #69a63f);
}

.thumb-sides::before {
  background:
    radial-gradient(circle at 28% 42%, #eab24a 0 10%, transparent 11%),
    radial-gradient(circle at 52% 59%, #f7d766 0 12%, transparent 13%),
    radial-gradient(circle at 70% 38%, #70aa3f 0 12%, transparent 13%),
    linear-gradient(135deg, #f4cc55, #fff0a7);
}

.builder-block {
  background:
    linear-gradient(180deg, rgba(255, 253, 247, 0.88), rgba(255, 247, 233, 0.86));
}

.builder-heading {
  align-items: center;
}

.portion-guide {
  color: var(--brown-2);
}

.portion-guide strong {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: var(--paper);
  color: var(--green-dark);
  font-size: 0.72rem;
}

.builder-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 12px;
}

.ingredient-panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(180deg, #fffaf0 0%, #fffdf8 100%);
  overflow: hidden;
  box-shadow: 0 8px 22px rgba(83, 51, 26, 0.06);
}

.ingredient-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 13px 8px;
}

.panel-kicker {
  font-size: 0.84rem;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.panel-emoji {
  font-size: 1.1rem;
}

.panel-photo {
  --size: 100%;
  width: calc(100% - 20px);
  height: 104px;
  margin: 0 10px 10px;
  border-radius: 18px;
}

.panel-photo span {
  font-size: 2.3rem;
}

.ingredient-options {
  padding: 0 10px 12px;
}

.ingredient-choice {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  padding: 8px 0;
  border-top: 1px solid rgba(234, 220, 200, 0.86);
  cursor: pointer;
}

.ingredient-choice:first-child {
  border-top: 0;
}

.ingredient-choice:focus {
  outline: 2px solid rgba(79, 123, 44, 0.45);
  outline-offset: 2px;
  border-radius: 10px;
}

.pick-dot {
  display: grid;
  place-items: center;
  width: 15px;
  height: 15px;
  border: 1.5px solid rgba(59, 27, 18, 0.45);
  border-radius: 50%;
  color: var(--paper);
  font-size: 0.64rem;
  font-weight: 950;
  line-height: 1;
}

.ingredient-choice.is-active .pick-dot {
  border-color: var(--green);
  background: var(--green);
}

.choice-main {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.choice-name {
  overflow: hidden;
  color: var(--brown);
  font-size: 0.78rem;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.choice-cal {
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 760;
}

.portion-controls {
  display: inline-flex;
  gap: 3px;
}

.portion-btn {
  display: grid;
  place-items: center;
  width: 23px;
  height: 23px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: #fffaf0;
  color: var(--muted);
  font-size: 0.66rem;
  font-weight: 950;
  cursor: pointer;
}

.portion-btn:hover {
  border-color: rgba(79, 123, 44, 0.45);
}

.portion-btn.is-active {
  border-color: var(--green);
  background: var(--green);
  color: #fff;
}

.skip-pill {
  padding: 5px 8px;
  border: 1px dashed var(--line-strong);
  border-radius: 999px;
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 900;
}

.presets-block,
.compare-block {
  background: rgba(255, 253, 247, 0.66);
}

.section-heading.compact {
  margin-bottom: 12px;
}

.preset-list {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 10px;
}

.preset-card {
  display: grid;
  grid-template-columns: 50px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 74px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--brown);
  text-align: left;
  cursor: pointer;
  box-shadow: 0 7px 18px rgba(83, 51, 26, 0.05);
  transition: transform 0.18s ease, border-color 0.18s ease;
}

.preset-card:hover {
  transform: translateY(-2px);
  border-color: rgba(79, 123, 44, 0.42);
}

.preset-thumb {
  --size: 50px;
}

.preset-thumb span {
  font-size: 1.25rem;
}

.preset-card strong {
  display: block;
  margin-bottom: 2px;
  overflow: hidden;
  font-size: 0.78rem;
  font-weight: 950;
  line-height: 1.16;
}

.preset-card small {
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 760;
  line-height: 1.2;
}

.preset-card em {
  color: var(--green);
  font-style: normal;
  font-weight: 950;
}

.compare-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.compare-card {
  position: relative;
  padding: 16px;
  min-height: 162px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    radial-gradient(circle at 0 100%, rgba(255, 216, 77, 0.16), transparent 12rem),
    var(--paper);
  overflow: hidden;
  box-shadow: 0 8px 20px rgba(83, 51, 26, 0.05);
}

.compare-copy strong {
  display: block;
  color: var(--brown);
  font-size: 0.88rem;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.compare-copy small {
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 750;
}

.compare-visual {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 16px 0 12px;
}

.compare-emoji {
  display: grid;
  place-items: center;
  width: 62px;
  height: 46px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: #fff6dc;
  font-size: 1.8rem;
  box-shadow: inset 0 0 18px rgba(255, 255, 255, 0.55);
}

.vs-pill {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--green);
  color: #fff;
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
}

.compare-values {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.compare-values span {
  padding: 8px;
  border: 1px solid rgba(234, 220, 200, 0.78);
  border-radius: 12px;
  background: rgba(255, 250, 240, 0.74);
  font-weight: 950;
  color: var(--green-dark);
}

.compare-values b {
  display: block;
  margin-bottom: 2px;
  color: var(--muted);
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.compare-note {
  margin: 10px 0 0;
  color: var(--coral);
  font-size: 0.82rem;
  font-weight: 950;
}

.source-strip {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1.1fr) minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  margin: 0;
  padding: 22px 28px;
  background:
    linear-gradient(90deg, rgba(79, 123, 44, 0.14), rgba(255, 216, 77, 0.16)),
    #f6f0cf;
  border-top: 1px solid rgba(79, 123, 44, 0.16);
}

.source-illustration {
  display: grid;
  place-items: center;
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: rgba(255, 253, 247, 0.72);
  font-size: 2.1rem;
  box-shadow: inset 0 0 24px rgba(255, 255, 255, 0.7);
}

.source-card h2,
.summary-card h2 {
  margin-bottom: 8px;
  font-size: 0.98rem;
  font-weight: 950;
  color: var(--green-dark);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.source-card p,
.summary-card p {
  margin-bottom: 0;
  color: #67583f;
  font-size: 0.86rem;
  font-weight: 650;
  line-height: 1.55;
}

.summary-card {
  min-width: 0;
}

#mealSummaryInline {
  overflow: hidden;
  display: -webkit-box;
  min-height: 42px;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.summary-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  background: var(--green);
  border-color: var(--green);
  color: #fff;
}

.lime-doodle {
  display: grid;
  place-items: center;
  width: 90px;
  height: 64px;
  color: var(--green);
  font-size: 3rem;
  transform: rotate(-12deg);
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  z-index: 80;
  transform: translate(-50%, 22px);
  padding: 12px 16px;
  border: 1px solid rgba(79, 123, 44, 0.25);
  border-radius: 999px;
  background: var(--green-dark);
  color: #fff;
  font-size: 0.86rem;
  font-weight: 900;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.18);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease;
}

.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

.mobile-total,
.mobile-nav {
  display: none;
}

@media (max-width: 1180px) {
  .hero-utility {
    grid-template-columns: 1fr;
  }

  .hero-copy {
    text-align: left;
    justify-self: stretch;
  }

  .top-actions {
    min-width: 0;
    justify-content: flex-start;
  }

  .totals-band {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .stat-tile:nth-child(4n) {
    border-right: 0;
  }

  .stat-tile:nth-child(-n + 4) {
    border-bottom: 1px solid rgba(116, 80, 25, 0.17);
  }

  .builder-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .preset-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  body {
    padding-bottom: 176px;
    background:
      radial-gradient(circle at 0 0, rgba(255, 216, 77, 0.32), transparent 17rem),
      linear-gradient(180deg, #fffdf7, var(--cream));
  }

  .bg-doodle,
  .desktop-nav {
    display: none;
  }

  .app-shell {
    width: 100%;
    padding: 0;
  }

  .topline {
    position: sticky;
    top: 0;
    z-index: 30;
    margin: 0;
    padding: 12px 14px;
    background: rgba(255, 248, 236, 0.92);
    border-bottom: 1px solid rgba(234, 220, 200, 0.82);
    backdrop-filter: blur(14px);
  }

  .wordmark {
    font-size: 1.16rem;
  }

  .wordmark-mark {
    width: 34px;
    height: 34px;
    font-size: 0.9rem;
  }

  .calculator-card {
    border: 0;
    border-radius: 0;
    box-shadow: none;
    background: transparent;
    overflow: visible;
  }

  .hero-utility {
    padding: 20px 16px 14px;
    gap: 16px;
  }

  .hero-copy {
    text-align: center;
  }

  .eyebrow {
    font-size: 0.7rem;
  }

  h1 {
    font-size: 2.15rem;
  }

  .lede {
    font-size: 0.92rem;
  }

  .top-actions {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .action {
    justify-content: center;
    padding: 10px 12px;
    font-size: 0.78rem;
  }

  .totals-band {
    position: sticky;
    top: 59px;
    z-index: 25;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    margin: 0 12px 18px;
    border-radius: 18px;
  }

  .stat-tile {
    min-height: 76px;
    display: block;
    padding: 12px 10px;
    border-right: 1px solid rgba(116, 80, 25, 0.15);
  }

  .stat-icon {
    display: none;
  }

  .stat-label {
    font-size: 0.6rem;
  }

  .stat-text strong {
    font-size: 1.25rem;
  }

  .stat-unit {
    font-size: 0.62rem;
  }

  .section-block {
    margin: 0 12px 14px;
    padding: 14px;
    border-radius: 20px;
  }

  .section-heading {
    display: block;
  }

  .section-heading > div {
    margin-bottom: 8px;
  }

  .section-heading p {
    font-size: 0.8rem;
  }

  .format-grid {
    display: flex;
    gap: 8px;
    overflow-x: auto;
    padding: 8px;
    border-radius: 18px;
    scroll-snap-type: x mandatory;
  }

  .format-grid::-webkit-scrollbar,
  .builder-grid::-webkit-scrollbar,
  .preset-list::-webkit-scrollbar {
    display: none;
  }

  .format-card {
    flex: 0 0 92px;
    min-height: 105px;
    border: 1px solid var(--line);
    border-radius: 16px;
    scroll-snap-align: start;
  }

  .format-card small {
    display: none;
  }

  .format-card .thumb {
    --size: 56px;
  }

  .builder-grid {
    display: flex;
    gap: 12px;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    padding-bottom: 4px;
  }

  .ingredient-panel {
    flex: 0 0 min(88vw, 390px);
    scroll-snap-align: center;
  }

  .panel-photo {
    height: 126px;
  }

  .choice-name {
    font-size: 0.84rem;
  }

  .portion-btn {
    width: 30px;
    height: 28px;
  }

  .preset-list {
    display: flex;
    overflow-x: auto;
    gap: 10px;
    scroll-snap-type: x mandatory;
  }

  .preset-card {
    flex: 0 0 245px;
    scroll-snap-align: start;
  }

  .compare-grid {
    grid-template-columns: 1fr;
  }

  .source-strip {
    grid-template-columns: 1fr;
    margin-top: 4px;
    padding: 18px 16px;
  }

  .source-illustration,
  .lime-doodle {
    display: none;
  }

  .mobile-total {
    display: block;
    position: fixed;
    z-index: 55;
    left: 10px;
    right: 10px;
    bottom: 68px;
  }

  .mobile-total-card {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 10px 14px;
    align-items: center;
    padding: 14px;
    border: 1px solid rgba(80, 49, 26, 0.16);
    border-radius: 22px;
    background: rgba(255, 253, 247, 0.94);
    box-shadow: 0 16px 46px rgba(50, 29, 12, 0.2);
    backdrop-filter: blur(18px);
  }

  .mobile-total-label {
    display: block;
    color: var(--muted);
    font-size: 0.68rem;
    font-weight: 950;
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }

  .mobile-total-card strong {
    display: inline-block;
    font-size: 1.75rem;
    line-height: 1;
    letter-spacing: -0.05em;
  }

  .mobile-total-card > div:first-child span:last-child {
    color: var(--muted);
    font-size: 0.76rem;
    font-weight: 800;
  }

  .mobile-mini-stats {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 6px;
  }

  .mobile-mini-stats span {
    padding: 5px 7px;
    border-radius: 999px;
    background: #fff3d3;
    color: var(--brown-2);
    font-size: 0.72rem;
    font-weight: 850;
  }

  .mobile-mini-stats b {
    color: var(--green);
  }

  .mobile-total-actions {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: 0.9fr 1.35fr;
    gap: 8px;
  }

  .mobile-total-actions button {
    width: 100%;
    border-radius: 16px;
  }

  .mobile-total-actions .primary {
    background: var(--green);
    border-color: var(--green);
    color: #fff;
  }

  .mobile-nav {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 60;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    padding: 8px 10px 9px;
    border-top: 1px solid rgba(80, 49, 26, 0.12);
    background: rgba(255, 253, 247, 0.95);
    box-shadow: 0 -12px 34px rgba(50, 29, 12, 0.09);
    backdrop-filter: blur(18px);
  }

  .mobile-nav a {
    display: grid;
    place-items: center;
    gap: 3px;
    color: var(--muted);
    font-size: 0.68rem;
    font-weight: 900;
  }

  .mobile-nav span {
    font-size: 1.08rem;
  }

  .mobile-nav a.is-active {
    color: var(--green);
  }

  .toast {
    bottom: 188px;
    width: max-content;
    max-width: calc(100% - 28px);
  }
}

@media (max-width: 430px) {
  .stat-tile {
    min-height: 70px;
    padding: 10px 8px;
  }

  .stat-text strong {
    font-size: 1.1rem;
  }

  .portion-controls {
    gap: 2px;
  }

  .portion-btn {
    width: 27px;
    height: 27px;
  }

  .ingredient-choice {
    grid-template-columns: 18px minmax(0, 1fr);
  }

  .portion-controls,
  .skip-pill {
    grid-column: 2 / -1;
    justify-self: start;
  }

  .mobile-mini-stats {
    justify-content: flex-start;
  }

  .mobile-total-card {
    grid-template-columns: 1fr;
  }
}

/* styles.css */
:root {
  --cream: #fff8ec;
  --cream-2: #fff2dc;
  --paper: #fffdf7;
  --paper-soft: #fff9ef;
  --yellow: #ffd84d;
  --yellow-deep: #efb821;
  --green: #4f7b2c;
  --green-dark: #2f4d1e;
  --olive: #65773a;
  --coral: #f06d38;
  --tomato: #b73520;
  --brown: #3b1b12;
  --brown-2: #693827;
  --muted: #826d5d;
  --line: #eadcc8;
  --line-strong: #dac6aa;
  --shadow: 0 24px 70px rgba(75, 43, 22, 0.12);
  --soft-shadow: 0 12px 30px rgba(87, 54, 28, 0.1);
  --radius-xl: 34px;
  --radius-lg: 22px;
  --radius-md: 16px;
  --radius-sm: 12px;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  color: var(--brown);
  background:
    radial-gradient(circle at 5% 8%, rgba(255, 216, 77, 0.24), transparent 24rem),
    radial-gradient(circle at 95% 10%, rgba(79, 123, 44, 0.12), transparent 22rem),
    linear-gradient(180deg, #fffdf7 0%, var(--cream) 100%);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font: inherit;
}

.bg-doodle {
  position: fixed;
  z-index: 0;
  color: rgba(79, 123, 44, 0.18);
  font-family: Georgia, serif;
  pointer-events: none;
  user-select: none;
}

.bg-doodle-left {
  left: 24px;
  bottom: 34px;
  font-size: 9rem;
  transform: rotate(-18deg);
}

.bg-doodle-right {
  top: 28px;
  right: 42px;
  font-size: 7rem;
  color: rgba(240, 109, 56, 0.16);
  transform: rotate(16deg);
}

.app-shell {
  position: relative;
  z-index: 1;
  width: min(1360px, calc(100% - 36px));
  margin: 0 auto;
  padding: 24px 0 64px;
}

.topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
  padding: 0 8px;
}

.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 1.5rem;
  font-weight: 900;
  letter-spacing: -0.04em;
  color: var(--green-dark);
}

.wordmark-mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 2px solid var(--green-dark);
  border-radius: 50%;
  background: var(--paper);
  box-shadow: 0 6px 0 rgba(47, 77, 30, 0.12);
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--brown-2);
  font-weight: 800;
  font-size: 0.88rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.desktop-nav a {
  padding: 12px 15px;
  border-radius: 999px;
}

.desktop-nav a:hover {
  background: rgba(255, 216, 77, 0.38);
}

.calculator-card {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.8), rgba(255, 249, 239, 0.96)),
    radial-gradient(circle at 3% 5%, rgba(79, 123, 44, 0.08), transparent 17rem);
  border: 1px solid var(--line);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.hero-utility {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 24px;
  align-items: start;
  padding: 34px 36px 24px;
}

.hero-copy {
  text-align: center;
  justify-self: center;
  max-width: 720px;
}

.eyebrow {
  margin: 0 0 8px;
  font-size: 0.78rem;
  font-weight: 900;
  color: var(--green);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 8px;
  font-family: Georgia, "Times New Roman", serif;
  color: var(--brown);
  font-size: clamp(2.05rem, 4vw, 3.35rem);
  line-height: 0.95;
  letter-spacing: -0.065em;
}

.lede {
  margin-bottom: 0;
  color: var(--brown-2);
  font-size: 1rem;
  line-height: 1.55;
}

.top-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 10px;
  min-width: 355px;
}

.action,
.summary-button,
.mobile-total-actions button {
  border: 1px solid var(--line-strong);
  background: var(--paper);
  color: var(--brown);
  border-radius: 999px;
  padding: 10px 14px;
  font-weight: 900;
  font-size: 0.84rem;
  cursor: pointer;
  box-shadow: 0 4px 0 rgba(80, 49, 26, 0.08);
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.action:hover,
.summary-button:hover,
.mobile-total-actions button:hover {
  transform: translateY(-1px);
  box-shadow: 0 7px 0 rgba(80, 49, 26, 0.1);
}

.action:active,
.summary-button:active,
.mobile-total-actions button:active {
  transform: translateY(1px);
  box-shadow: 0 2px 0 rgba(80, 49, 26, 0.1);
}

.action-warn {
  color: var(--coral);
  border-color: rgba(240, 109, 56, 0.35);
}

.action-green {
  color: var(--green);
  border-color: rgba(79, 123, 44, 0.35);
}

.action-outline {
  background: transparent;
  border-color: rgba(183, 53, 32, 0.36);
  color: var(--tomato);
}

.totals-band {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 0;
  margin: 0 36px 26px;
  border: 1px solid rgba(122, 83, 19, 0.2);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(255, 235, 120, 0.95), rgba(255, 211, 61, 0.98)),
    radial-gradient(circle at 10% 0%, rgba(255, 255, 255, 0.65), transparent 22rem);
  box-shadow: 0 16px 34px rgba(190, 130, 18, 0.18);
  overflow: hidden;
}

.stat-tile {
  min-height: 96px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 18px 16px;
  border-right: 1px solid rgba(116, 80, 25, 0.17);
}

.stat-tile:last-child {
  border-right: 0;
}

.stat-icon {
  display: grid;
  place-items: center;
  width: 36px;
  min-width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255, 253, 247, 0.52);
  font-size: 1.25rem;
}

.stat-text {
  min-width: 0;
  display: grid;
  grid-template-columns: auto auto;
  align-items: end;
  gap: 0 4px;
}

.stat-label {
  grid-column: 1 / -1;
  margin-bottom: 3px;
  font-size: 0.72rem;
  font-weight: 950;
  line-height: 1;
  color: var(--brown-2);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.stat-text strong {
  font-size: clamp(1.36rem, 2vw, 2rem);
  line-height: 0.9;
  letter-spacing: -0.04em;
}

.stat-unit {
  margin-bottom: 2px;
  color: var(--brown-2);
  font-size: 0.76rem;
  font-weight: 800;
}

.section-block {
  margin: 0 24px 14px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: rgba(255, 253, 247, 0.72);
}

.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 14px;
}

.section-heading > div {
  display: flex;
  align-items: center;
  gap: 11px;
}

.section-heading h2 {
  margin: 0;
  color: var(--brown);
  font-size: 1.08rem;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.section-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.4;
}

.step-badge,
.lightning,
.scale-icon {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  border-radius: 50%;
  background: var(--yellow);
  color: var(--brown);
  font-weight: 950;
  box-shadow: 0 4px 0 rgba(105, 56, 39, 0.13);
}

.lightning,
.scale-icon {
  background: transparent;
  color: var(--coral);
  font-size: 1.35rem;
  box-shadow: none;
}

.format-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  border: 1px solid var(--line-strong);
  border-radius: 18px;
  overflow: hidden;
  background: var(--paper);
}

.format-card {
  min-width: 0;
  display: grid;
  place-items: center;
  gap: 8px;
  padding: 16px 12px 14px;
  border: 0;
  border-right: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.68), rgba(255, 249, 239, 0.88));
  color: var(--brown);
  cursor: pointer;
  position: relative;
}

.format-card:last-child {
  border-right: 0;
}

.format-card::after {
  content: "";
  position: absolute;
  inset: 8px;
  border-radius: 14px;
  border: 2px solid transparent;
  pointer-events: none;
  transition: border-color 0.18s ease, background 0.18s ease;
}

.format-card:hover::after {
  border-color: rgba(79, 123, 44, 0.25);
}

.format-card.is-active::after {
  border-color: var(--green);
  background: rgba(79, 123, 44, 0.05);
}

.format-card strong {
  position: relative;
  z-index: 1;
  font-size: 0.88rem;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.format-card small {
  position: relative;
  z-index: 1;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 800;
}

.thumb {
  --size: 70px;
  position: relative;
  display: grid;
  place-items: center;
  width: var(--size);
  height: calc(var(--size) * 0.72);
  border: 1px solid rgba(97, 69, 45, 0.15);
  border-radius: 999px;
  overflow: hidden;
  box-shadow:
    inset 0 0 18px rgba(255, 255, 255, 0.42),
    0 8px 18px rgba(65, 38, 22, 0.14);
  isolation: isolate;
}

.thumb::before,
.thumb::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
}

.thumb::after {
  background:
    radial-gradient(circle at 25% 26%, rgba(255, 255, 255, 0.7), transparent 13%),
    radial-gradient(circle at 70% 80%, rgba(50, 30, 17, 0.14), transparent 22%);
  mix-blend-mode: soft-light;
}

.thumb span {
  font-size: calc(var(--size) * 0.36);
  filter: drop-shadow(0 3px 4px rgba(48, 28, 13, 0.2));
}

.thumb-bowl::before {
  background:
    radial-gradient(circle at 34% 50%, #7b3b22 0 9%, transparent 10%),
    radial-gradient(circle at 62% 40%, #6aaa3a 0 12%, transparent 13%),
    radial-gradient(circle at 45% 35%, #f36f2d 0 9%, transparent 10%),
