.builder-block {
  background:
    linear-gradient(180deg, rgba(255, 253, 247, 0.88), rgba(255, 247, 233, 0.86));
}

.builder-heading {
  align-items: center;
}

.portion-guide {
  color: var(--brown-2);
}

.portion-guide strong {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: var(--paper);
  color: var(--green-dark);
  font-size: 0.72rem;
}

.builder-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 12px;
}

.ingredient-panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(180deg, #fffaf0 0%, #fffdf8 100%);
  overflow: hidden;
  box-shadow: 0 8px 22px rgba(83, 51, 26, 0.06);
}

.ingredient-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 13px 8px;
}

.panel-kicker {
  font-size: 0.84rem;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.panel-emoji {
  font-size: 1.1rem;
}

.panel-photo {
  --size: 100%;
  width: calc(100% - 20px);
  height: 104px;
  margin: 0 10px 10px;
  border-radius: 18px;
}

.panel-photo span {
  font-size: 2.3rem;
}

.ingredient-options {
  padding: 0 10px 12px;
}

.ingredient-choice {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  padding: 8px 0;
  border-top: 1px solid rgba(234, 220, 200, 0.86);
  cursor: pointer;
}

.ingredient-choice:first-child {
  border-top: 0;
}

.ingredient-choice:focus {
  outline: 2px solid rgba(79, 123, 44, 0.45);
  outline-offset: 2px;
  border-radius: 10px;
}

.pick-dot {
  display: grid;
  place-items: center;
  width: 15px;
  height: 15px;
  border: 1.5px solid rgba(59, 27, 18, 0.45);
  border-radius: 50%;
  color: var(--paper);
  font-size: 0.64rem;
  font-weight: 950;
  line-height: 1;
}

.ingredient-choice.is-active .pick-dot {
  border-color: var(--green);
  background: var(--green);
}

.choice-main {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.choice-name {
  overflow: hidden;
  color: var(--brown);
  font-size: 0.78rem;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.choice-cal {
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 760;
}

.portion-controls {
  display: inline-flex;
  gap: 3px;
}

.portion-btn {
  display: grid;
  place-items: center;
  width: 23px;
  height: 23px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: #fffaf0;
  color: var(--muted);
  font-size: 0.66rem;
  font-weight: 950;
  cursor: pointer;
}

.portion-btn:hover {
  border-color: rgba(79, 123, 44, 0.45);
}

.portion-btn.is-active {
  border-color: var(--green);
  background: var(--green);
  color: #fff;
}

.skip-pill {
  padding: 5px 8px;
  border: 1px dashed var(--line-strong);
  border-radius: 999px;
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 900;
}

.presets-block,
.compare-block {
  background: rgba(255, 253, 247, 0.66);
}

.section-heading.compact {
