  cursor: pointer;
  box-shadow: 0 7px 18px rgba(83, 51, 26, 0.05);
  transition: transform 0.18s ease, border-color 0.18s ease;
}

.preset-card:hover {
  transform: translateY(-2px);
  border-color: rgba(79, 123, 44, 0.42);
}

.preset-thumb {
  --size: 50px;
}

.preset-thumb span {
  font-size: 1.25rem;
}

.preset-card strong {
