  margin-bottom: 2px;
  overflow: hidden;
  font-size: 0.78rem;
  font-weight: 950;
  line-height: 1.16;
}

.preset-card small {
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 760;
  line-height: 1.2;
}

.preset-card em {
  color: var(--green);
  font-style: normal;
  font-weight: 950;
}

.compare-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.compare-card {
  position: relative;
  padding: 16px;
  min-height: 162px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    radial-gradient(circle at 0 100%, rgba(255, 216, 77, 0.16), transparent 12rem),
    var(--paper);
  overflow: hidden;
  box-shadow: 0 8px 20px rgba(83, 51, 26, 0.05);
}

.compare-copy strong {
  display: block;
  color: var(--brown);
  font-size: 0.88rem;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.compare-copy small {
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 750;
}

.compare-visual {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 16px 0 12px;
}

.compare-emoji {
  display: grid;
  place-items: center;
  width: 62px;
  height: 46px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: #fff6dc;
  font-size: 1.8rem;
  box-shadow: inset 0 0 18px rgba(255, 255, 255, 0.55);
}

.vs-pill {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--green);
  color: #fff;
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
}

.compare-values {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.compare-values span {
  padding: 8px;
  border: 1px solid rgba(234, 220, 200, 0.78);
  border-radius: 12px;
  background: rgba(255, 250, 240, 0.74);
  font-weight: 950;
  color: var(--green-dark);
}

.compare-values b {
  display: block;
  margin-bottom: 2px;
  color: var(--muted);
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.compare-note {
  margin: 10px 0 0;
  color: var(--coral);
  font-size: 0.82rem;
  font-weight: 950;
}

.source-strip {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1.1fr) minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  margin: 0;
  padding: 22px 28px;
  background:
    linear-gradient(90deg, rgba(79, 123, 44, 0.14), rgba(255, 216, 77, 0.16)),
    #f6f0cf;
  border-top: 1px solid rgba(79, 123, 44, 0.16);
}

.source-illustration {
  display: grid;
  place-items: center;
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: rgba(255, 253, 247, 0.72);
  font-size: 2.1rem;
  box-shadow: inset 0 0 24px rgba(255, 255, 255, 0.7);
}

.source-card h2,
.summary-card h2 {
  margin-bottom: 8px;
  font-size: 0.98rem;
  font-weight: 950;
  color: var(--green-dark);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.source-card p,
.summary-card p {
  margin-bottom: 0;
  color: #67583f;
  font-size: 0.86rem;
  font-weight: 650;
  line-height: 1.55;
}

.summary-card {
  min-width: 0;
}

#mealSummaryInline {
  overflow: hidden;
  display: -webkit-box;
  min-height: 42px;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.summary-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  background: var(--green);
  border-color: var(--green);
  color: #fff;
}

.lime-doodle {
  display: grid;
  place-items: center;
  width: 90px;
  height: 64px;
  color: var(--green);
  font-size: 3rem;
  transform: rotate(-12deg);
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  z-index: 80;
  transform: translate(-50%, 22px);
  padding: 12px 16px;
  border: 1px solid rgba(79, 123, 44, 0.25);
  border-radius: 999px;
  background: var(--green-dark);
  color: #fff;
  font-size: 0.86rem;
  font-weight: 900;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.18);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease;
}

.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

.mobile-total,
.mobile-nav {
  display: none;
}

@media (max-width: 1180px) {
