@media (max-width: 430px) {
  .stat-tile {
    min-height: 70px;
    padding: 10px 8px;
  }

  .stat-text strong {
    font-size: 1.1rem;
  }

  .portion-controls {
    gap: 2px;
  }

  .portion-btn {
    width: 27px;
    height: 27px;
  }

  .ingredient-choice {
    grid-template-columns: 18px minmax(0, 1fr);
  }

  .portion-controls,
  .skip-pill {
    grid-column: 2 / -1;
    justify-self: start;
  }

  .mobile-mini-stats {
    justify-content: flex-start;
  }

  .mobile-total-card {
    grid-template-columns: 1fr;
  }
}

