// script.js
const $ = (selector) => document.querySelector(selector);

const els = {
  totalsBand: $('#totalsBand'),
  mobileTotal: $('#mobileTotal'),
  mealFormats: $('#mealFormats'),
  ingredientGroups: $('#ingredientGroups'),
  presetList: $('#presetList'),
  compareCards: $('#compareCards'),
  mealSummaryInline: $('#mealSummaryInline'),
  toast: $('#toast')
};

const ZERO = {
  calories: 0,
  protein: 0,
  carbs: 0,
  fat: 0,
  sodium: 0,
  fiber: 0,
  sugar: 0,
  satFat: 0
