function cloneState(st = state) {
  return {
    format: st.format,
    selected: {
      rice: st.selected.rice,
      beans: st.selected.beans,
      protein: st.selected.protein,
      salsa: new Set([...st.selected.salsa]),
      toppings: new Set([...st.selected.toppings]),
      sides: new Set([...st.selected.sides])
    },
    portions: { ...st.portions }
  };
}

function addNutrition(total, nutrition, multiplier = 1) {
  Object.keys(ZERO).forEach((key) => {
    total[key] += (nutrition[key] || 0) * multiplier;
  });
}

function addItemToTotal(total, st, itemId) {
  const item = itemMap.get(itemId);
  if (!item || item.isNone) return;

  const portion = st.portions[itemId] || 'normal';
  addNutrition(total, item.nutrition, PORTIONS[portion]?.mult || 1);
}

function calculate(st = state) {
  const total = { ...ZERO };
  const format = mealFormats.find((item) => item.id === st.format);

  if (format) addNutrition(total, format.base, 1);

  groups.forEach((group) => {
    if (group.multi) {
      st.selected[group.id].forEach((itemId) => addItemToTotal(total, st, itemId));
    } else {
      addItemToTotal(total, st, st.selected[group.id]);
    }
  });

  return Object.fromEntries(
    Object.entries(total).map(([key, value]) => [
      key,
      key === 'calories' || key === 'sodium' ? Math.round(value) : Math.round(value * 10) / 10
    ])
  );
}

function formatNumber(key, value) {
  if (key === 'calories' || key === 'sodium') return Math.round(value).toLocaleString('en-US');
  return Number.isInteger(value) ? value.toFixed(0) : value.toFixed(1);
}

function isSelected(group, itemId, st = state) {
  return group.multi ? st.selected[group.id].has(itemId) : st.selected[group.id] === itemId;
}

