  group.items.forEach((item) => itemMap.set(item.id, { ...item, groupId: group.id }));
});

function blankState() {
  return {
    format: 'bowl',
    selected: {
      rice: 'noRice',
      beans: 'noBeans',
      protein: 'noProtein',
      salsa: new Set(),
      toppings: new Set(),
      sides: new Set()
    },
    portions: {}
  };
}

function setSingle(st, groupId, itemId, portion = 'normal') {
  st.selected[groupId] = itemId;
  if (!itemMap.get(itemId)?.isNone) {
    st.portions[itemId] = portion;
  }
  return st;
}

function addMulti(st, groupId, itemId, portion = 'normal') {
  st.selected[groupId].add(itemId);
  st.portions[itemId] = portion;
  return st;
}

function makeConfiguredState(format, singles = {}, multis = {}) {
  const st = blankState();
  st.format = format;

  Object.entries(singles).forEach(([groupId, value]) => {
    const [itemId, portion = 'normal'] = Array.isArray(value) ? value : [value, 'normal'];
    setSingle(st, groupId, itemId, portion);
  });

  Object.entries(multis).forEach(([groupId, items]) => {
    Object.entries(items).forEach(([itemId, portion = 'normal']) => addMulti(st, groupId, itemId, portion));
  });

  return st;
}

