  const calories = item.isNone ? 0 : Math.round((item.nutrition.calories || 0) * multiplier);

  return `
    <div class="ingredient-choice ${active ? 'is-active' : ''} ${item.isNone ? 'is-empty' : ''}"
      data-group="${group.id}" data-ingredient="${item.id}" role="button" tabindex="0" aria-pressed="${active}">
      <span class="pick-dot" aria-hidden="true">${active ? '✓' : ''}</span>
      <span class="choice-main">
        <span class="choice-name">${item.label}</span>
        <span class="choice-cal">${calories} cal</span>
      </span>
      ${item.isNone ? `<span class="skip-pill">Skip</span>` : `
        <span class="portion-controls" aria-label="${item.label} portion controls">
