function renderCompareCards() {
  const bowlState = cloneState();
  bowlState.format = 'bowl';

  const burritoState = cloneState();
  burritoState.format = 'burrito';

  const bowlCal = calculate(bowlState).calories;
  const burritoCal = calculate(burritoState).calories;

  const selectedRice = state.selected.rice && state.selected.rice !== 'noRice' ? state.selected.rice : 'whiteRice';

  const normalRiceState = cloneState();
  setSingle(normalRiceState, 'rice', selectedRice, 'normal');

  const extraRiceState = cloneState();
  setSingle(extraRiceState, 'rice', selectedRice, 'extra');

  const normalRiceCal = calculate(normalRiceState).calories;
  const extraRiceCal = calculate(extraRiceState).calories;

  const withChipsState = cloneState();
  withChipsState.selected.sides.add('chips');
  withChipsState.portions.chips = withChipsState.portions.chips || 'normal';

  const withoutChipsState = cloneState();
  withoutChipsState.selected.sides.delete('chips');
  withoutChipsState.selected.sides.delete('chipsGuac');
  delete withoutChipsState.portions.chips;
  delete withoutChipsState.portions.chipsGuac;

  const withChipsCal = calculate(withChipsState).calories;
  const withoutChipsCal = calculate(withoutChipsState).calories;

  const cards = [
    {
      title: 'Bowl vs Burrito',
      subtitle: 'Same ingredients, different format',
      leftLabel: 'Bowl',
      leftValue: bowlCal,
      rightLabel: 'Burrito',
      rightValue: burritoCal,
      note: `${diffText(burritoCal - bowlCal)} as a burrito`,
      emoji: '🌯'
    },
    {
      title: 'Normal vs Extra Rice',
      subtitle: itemMap.get(selectedRice)?.label || 'White Rice',
      leftLabel: 'Normal',
      leftValue: normalRiceCal,
      rightLabel: 'Extra',
      rightValue: extraRiceCal,
      note: `${diffText(extraRiceCal - normalRiceCal)} with extra rice`,
      emoji: '🍚'
    },
    {
      title: 'With vs Without Chips',
      subtitle: 'Crunch changes the total fast',
      leftLabel: 'With Chips',
      leftValue: withChipsCal,
      rightLabel: 'Without',
      rightValue: withoutChipsCal,
      note: `${diffText(withChipsCal - withoutChipsCal)} from chips`,
      emoji: '🔺'
    }
  ];

  els.compareCards.innerHTML = cards.map((card) => `
    <article class="compare-card">
      <div class="compare-copy">
        <strong>${card.title}</strong>
        <small>${card.subtitle}</small>
